/**
 * Complete App UI Catalog metadata, polish inconsistency queue, unpromoted patterns,
 * and agent quick-pick guide. Excludes marketing/homepage pages.
 * Generated file/usage counts live in ../catalogIndex.json (built by tools/internal/build-ui-catalog.mjs).
 */

export type PartCategory =
  | 'Actions'
  | 'Inputs & Settings'
  | 'Overlays & Menus'
  | 'Feedback & Status'
  | 'Data, Lists & Cards'
  | 'Trackers & Calendar'
  | 'Brand & Icons'
  | 'Product Flows';

type PartStatus = 'canonical' | 'direct' | 'shared' | 'flow';

export interface CatalogPartDef {
  id: string;
  name: string;
  category: PartCategory;
  status: PartStatus;
  summary: string;
  importCode: string;
  source: string;
  useFor: string;
  never: string;
  consumerSymbols: string[];
  lintRules?: string[];
  driftNotes?: string[];
  internalNotes?: string[];
  keywords?: string;
}

export interface InconsistencyItem {
  id: string;
  wave: number;
  waveName: string;
  severity: 'critical' | 'high' | 'medium' | 'low';
  category: string;
  title: string;
  detail: string;
  canonicalTarget: string;
  locations: string[];
}

export interface UnpromotedPattern {
  id: string;
  name: string;
  proposedPart: string;
  currentFiles: string[];
  whyPromote: string;
  driftToday: string;
}

export interface AgentPickRow {
  need: string;
  usePart: string;
  importCode: string;
  recipe: string;
  avoidCopying: string;
}

export interface HiddenStateItem {
  id: string;
  area: string;
  file: string;
  trigger: string;
  triggerKind: 'switch' | 'select' | 'segmented' | 'button' | 'gate';
  reveals: string;
  availability: 'demo' | 'account' | 'desktop' | 'native' | 'pro';
  driftNote?: string;
}

export const PART_CATEGORIES: readonly PartCategory[] = [
  'Actions',
  'Inputs & Settings',
  'Overlays & Menus',
  'Feedback & Status',
  'Data, Lists & Cards',
  'Trackers & Calendar',
  'Brand & Icons',
  'Product Flows',
];

